/**
 * Builds public/worklets/time-stretch.js: the AudioWorklet the browser loads for tempo/pitch stretching.
 *
 * An AudioWorklet module can't import from node_modules, so this concatenates SoundTouchJS (the ES module, with its
 * `export` line removed so its classes become plain top-level declarations) and src/worklets/time-stretch-processor.js
 * into one file. The output is committed (like public/wasm/**) and a unit test fails when it is stale, so run
 * `npm run build:worklet` after changing the processor or upgrading soundtouchjs.
 *
 * SoundTouchJS is LGPL-2.1: its copyright and license header is kept at the top of the generated file.
 */
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
export const WORKLET_OUTPUT = resolve(root, "public/worklets/time-stretch.js");

export function buildStretchWorklet() {
  const library = readFileSync(resolve(root, "node_modules/soundtouchjs/dist/soundtouch.js"), "utf8");
  const processor = readFileSync(resolve(root, "src/worklets/time-stretch-processor.js"), "utf8");
  const stripped = library
    .replace(/^export \{[^}]*\};?\s*$/m, "")
    .replace(/^\/\/# sourceMappingURL=.*$/m, "")
    .trimEnd();
  if (/^export\s/m.test(stripped) || /^import\s/m.test(stripped)) {
    throw new Error("soundtouch.js still has an import/export after stripping; the build script needs updating.");
  }
  return [
    "// GENERATED by scripts/build-stretch-worklet.mjs — do not edit. Edit src/worklets/time-stretch-processor.js and run `npm run build:worklet`.",
    stripped,
    "",
    "// ---- src/worklets/time-stretch-processor.js ----",
    processor.trimEnd(),
    "",
  ].join("\n");
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  mkdirSync(dirname(WORKLET_OUTPUT), { recursive: true });
  writeFileSync(WORKLET_OUTPUT, buildStretchWorklet());
  console.log("wrote", WORKLET_OUTPUT);
}
